  container.append(statusbar);
  const listeners = new Map<string, Array<(event?: unknown) => void>>();
  return {
    execCommand: vi.fn(),
    getContainer: vi.fn(() => container),
    on: vi.fn((name: string, callback: (event?: unknown) => void) => {
